import React, { useRef } from "react";
import Nav from "./nav";
import LandingPage from "./landingPage";
import Passions from "./passions";

export default function Home() {
  const scrollRef = useRef(null);

  const handleMouseMove = (e) => {
    const container = scrollRef.current;
    if (!container) return;

    const containerHeight = container.clientHeight;
    const scrollHeight = container.scrollHeight;
    const mouseY = e.clientY;

    // Calculate percentage of mouse Y position relative to screen
    const percent = mouseY / window.innerHeight;

    // Calculate target scroll position
    const targetScroll = percent * (scrollHeight - containerHeight);

    container.scrollTo({
      top: targetScroll,
      behavior: "smooth", // Optional for smoother scrolling
    });
  };

  return (
    <div className="w-full h-screen flex font-poppins overflow-hidden">
      <Nav />
      {/* Left: Fixed image */}
      <div
        className="w-1/2 h-full fixed top-0 left-0 z-0"
        onMouseMove={handleMouseMove}
      >
        <div
          className="w-full h-full bg-no-repeat bg-cover bg-center"
          style={{ backgroundImage: "url('/landingPage/lpImage.jpeg')" }}
        ></div>
      </div>

      {/* Right: Scrollable content */}
      <div
        className="w-1/2 ml-auto h-screen overflow-y-auto z-10"
        ref={scrollRef}
      >
        <LandingPage />
        <Passions />
      </div>
    </div>
  );
}
